Tool response:
Tool: find_available_units
Description: Search for all residential units in a specified property that are currently vacant or available soon,
have the specified number of bedrooms, at least the minimum number of bathrooms, and a monthly rent
no higher than the maximum rent. Returns unit number, floor plan, square footage, rent amount,
availability date, and amenities, sorted by availability date ascending.
Parameters:
    {
      "type": "object",
      "properties": {
        "property_id": {
          "type": "integer",
          "title": "Property Id",
          "description": ""
        },
        "bedrooms": {
          "type": "integer",
          "description": "Number of bedrooms (default: 2)",
          "default": 2,
          "title": "Bedrooms"
        },
        "min_bathrooms": {
          "type": "number",
          "description": "Minimum number of bathrooms (default: 1)",
          "default": 1.0,
          "title": "Min Bathrooms"
        },
        "max_rent": {
          "type": "number",
          "description": "Maximum monthly rent amount (default: 2200)",
          "default": 2200.0,
          "title": "Max Rent"
        }
      },
      "required": [
        "property_id"
      ]
    }
